/* Analytics: systems, page titles and carts (round Z6). analytics_events gets page_title, the title of the page a view was of, so Top pages names each path by its title; nullable, at most 200 characters, checked for new rows only (NOT VALID). analytics_audience counts, for one creator, one property (or all of them), optionally one product and one period: unique visitors and page views by operating system (iOS, Android, Windows, macOS, Linux, ChromeOS and the rest as stored), the unique visitors who added something to the cart (buy_click), and the latest title of each page viewed. It reads analytics_events through the indexes part 25 and part 61 made (creator, event type, time; creator, property, event type, time), so no new index is needed. Server only: not SECURITY DEFINER, and only the service role may run it. No row changes. Until it runs, Analytics counts the same figures from the rows. Safe to run again. */
ALTER TABLE IF EXISTS public.analytics_events ADD COLUMN IF NOT EXISTS page_title text;
DO $do$ BEGIN IF to_regclass('public.analytics_events') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'analytics_events_page_title_length') THEN ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_page_title_length CHECK (page_title IS NULL OR length(page_title) <= 200) NOT VALID; END IF; END $do$;
CREATE OR REPLACE FUNCTION public.analytics_audience(p_creator_id uuid, p_property_type text, p_property_id uuid, p_default_website uuid, p_product_id uuid, p_start timestamptz, p_end timestamptz) RETURNS jsonb LANGUAGE sql STABLE SET search_path = public AS $f$ WITH e AS (SELECT a.event_type, a.os, a.property_type, a.property_id, a.path, a.page_title, a.created_at, coalesce(nullif(a.visitor_id, ''), nullif(a.session_id, ''), 'e:' || a.id::text) AS who FROM public.analytics_events a WHERE a.creator_id = p_creator_id AND a.event_type IN ('view', 'buy_click') AND a.created_at >= p_start AND a.created_at < p_end AND (p_property_type IS NULL OR (a.property_type = p_property_type AND (p_property_type <> 'website' OR a.property_id = p_property_id OR (a.property_id IS NULL AND p_default_website IS NOT NULL AND p_property_id = p_default_website)))) AND (p_product_id IS NULL OR a.product_id = p_product_id)), v AS (SELECT * FROM e WHERE e.event_type = 'view') SELECT jsonb_build_object('os', coalesce((SELECT jsonb_agg(jsonb_build_array(o.k, o.people, o.views) ORDER BY o.people DESC, o.k) FROM (SELECT coalesce(nullif(btrim(v.os), ''), 'unknown') AS k, count(DISTINCT v.who)::int AS people, count(*)::int AS views FROM v GROUP BY 1 ORDER BY 2 DESC, 1 LIMIT 40) o), '[]'::jsonb), 'carts', (SELECT count(DISTINCT e.who)::int FROM e WHERE e.event_type = 'buy_click'), 'titles', coalesce((SELECT jsonb_agg(jsonb_build_array(t.property_type, t.property_id, t.path, t.page_title)) FROM (SELECT DISTINCT ON (v.property_type, v.property_id, v.path) v.property_type, v.property_id, v.path, v.page_title FROM v WHERE v.page_title IS NOT NULL AND v.path IS NOT NULL ORDER BY v.property_type, v.property_id, v.path, v.created_at DESC LIMIT 2000) t), '[]'::jsonb)) $f$;
REVOKE ALL ON FUNCTION public.analytics_audience(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.analytics_audience(uuid, text, uuid, uuid, uuid, timestamptz, timestamptz) TO service_role;
